// Code node — מנרמל פריטי RSS משני המקורות לרשומות trends אחידות.
// מחשב viral_score פשוט: views/age_hours (כשיש), אחרת לפי traffic estimate.
const items = $input.all();
const out = [];
const now = Date.now();

for (const it of items) {
  const j = it.json || {};
  // Google Trends — title + ht:approx_traffic
  const title = j.title || j['ht:news_item_title'] || '';
  const link = j.link || j.url || '';
  const pubRaw = j.pubDate || j.isoDate || j['dc:date'] || null;
  const pubMs = pubRaw ? Date.parse(pubRaw) : now;
  const ageHours = Math.max(1, (now - pubMs) / 3600000);

  // traffic estimate — מגיע כ"50,000+" או "200K+"
  const trafficStr = (j['ht:approx_traffic'] || '').toString();
  const trafficNum = parseInt(trafficStr.replace(/[^0-9]/g, ''), 10) || 0;

  // אם זה YouTube trending אין traffic — נשתמש בעמדה ברשימה לאיתות פופולריות
  const positionScore = (1 / (it.pairedItem?.item || 1)) * 1000;

  const views = trafficNum || positionScore;
  const viral_score = views / ageHours;

  // hashtag מחושב מהמילה הראשונה — אילוץ ייחודי לזיהוי כפולים
  const hashtag = '#' + (title.split(/\s+/)[0] || 'trend').toLowerCase().replace(/[^a-z0-9]/g, '');
  const platform = link.includes('youtube.com') ? 'youtube' : 'google';

  out.push({
    json: {
      keyword: title.slice(0, 200),
      hashtag,
      platform,
      score: Math.round(viral_score * 100) / 100,
      source: link,
      payload: {
        link,
        traffic: trafficNum,
        published_at: new Date(pubMs).toISOString(),
        viral_score,
      },
    }
  });
}

return out;
